package plugin

const apiKeyShareMarkup = `<section id="apiKeySharePanel" class="panel" hidden><div class="panel-head"><div class="panel-title-wrap"><h2 class="panel-title" data-i18n="apiKey.shareTitle">API Key usage share</h2><p class="panel-subtitle" data-i18n="apiKey.shareHint">Current time, source and API Key filters. Set a name using the edit button. Model chart selections do not change this ranking.</p></div><div id="apiKeyShareMetric" class="panel-actions" role="group"><button type="button" class="control" data-api-key-share-metric="requests" aria-pressed="true" data-i18n="chart.requests">Requests</button><button type="button" class="control" data-api-key-share-metric="tokens" aria-pressed="false" data-i18n="chart.totalTokens">Total tokens</button><button type="button" class="control" data-api-key-share-metric="cost" aria-pressed="false" data-i18n="apiKey.totalCost">Total cost</button></div></div><div class="apikey-share-content"><svg id="apiKeyShareDonut" viewBox="0 0 280 280" role="img" data-i18n-aria="apiKey.shareTitle"></svg><div class="table-scroll"><table><thead><tr><th data-i18n="apiKey.name">Name / description</th><th data-i18n="chart.requests">Requests</th><th data-i18n="chart.totalTokens">Total tokens</th><th data-i18n="apiKey.totalCost" data-i18n-title="apiKey.costHint">Total cost</th><th data-i18n="apiKey.failed">Failures</th><th data-i18n="apiKey.share">Share</th></tr></thead><tbody id="apiKeyShareRows"></tbody></table></div></div><p id="apiKeyShareEmpty" class="panel-subtitle" hidden data-i18n="empty.calls">No requests</p></section>`

const apiKeyShareStyles = `
#apiKeySharePanel{margin-bottom:18px;padding:16px 22px 22px;min-width:0}#apiKeySharePanel .panel-head{padding:0 0 16px;align-items:flex-start}#apiKeySharePanel .panel-title{font-size:16px}#apiKeySharePanel .panel-subtitle{max-width:760px;line-height:1.65;margin:6px 0 0}#apiKeySharePanel .panel-actions{flex-shrink:0}#apiKeySharePanel[hidden],#apiKeyShareEmpty[hidden]{display:none!important}.apikey-share-content{display:grid;grid-template-columns:210px minmax(0,1fr);align-items:center;gap:24px;padding:16px 0 0;border-top:1px solid var(--border-color)}.apikey-share-content>svg{width:100%;max-width:210px}.apikey-share-content .table-scroll{min-width:0;max-height:420px;overflow:auto;border:1px solid var(--border-color);border-radius:10px}.apikey-share-content table{width:100%;min-width:610px;border-collapse:collapse}.apikey-share-content th{position:sticky;top:0;background:var(--bg-primary);z-index:1;white-space:nowrap}.apikey-share-content tbody tr:hover{background:var(--bg-tertiary)}.apikey-share-content td,.apikey-share-content th{padding:10px;text-align:right}.apikey-share-content td:first-child,.apikey-share-content th:first-child{text-align:left}.apikey-share-content .apikey-cell{max-width:260px;min-width:140px}.apikey-share-content .apikey-cell-value{font-weight:650}.apikey-share-swatch{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:7px;flex-shrink:0}#apiKeyShareMetric [aria-pressed=true]{border-color:var(--primary-color);color:var(--primary-color)}@media(max-width:720px){#apiKeySharePanel{padding:16px}#apiKeySharePanel .panel-head{flex-direction:column;gap:12px}#apiKeySharePanel .panel-actions{justify-content:flex-start}.apikey-share-content{gap:16px}.apikey-share-content{grid-template-columns:minmax(0,1fr)}.apikey-share-content>svg{margin:auto;width:200px}}
`

const apiKeyShareScript = `
var apiKeyShareMetric='requests';
function maskedAPIKey(key){key=String(key||'');return key?key.slice(0,Math.min(3,key.length))+'••••'+(key.length>6?key.slice(-3):''):t('apiKey.unnamed');}
function apiKeyShareName(item){return apiKeyLabels[item.ref]||t('apiKey.unnamed');}
function apiKeyShareCost(item){return currentCosts&&Array.isArray(currentCosts.api_keys)?currentCosts.api_keys.find(function(cost){return cost.ref===item.ref;})||null:null;}
function apiKeyShareCostText(item){var cost=apiKeyShareCost(item);return !cost||!cost.priced_requests?t('value.unavailable'):money(cost.total_usd)+(cost.unpriced_requests?' *':'');}
function apiKeyShareValue(item){if(apiKeyShareMetric==='cost'){var cost=apiKeyShareCost(item);return cost?Number(cost.total_usd||0):0;}return Number(item[apiKeyShareMetric==='tokens'?'total_tokens':'requests']||0);}
function showAPIKeyShareTooltip(event,item,percent){tooltipTitle(item.unknown?t('apiKey.untracked'):apiKeyShareName(item));tooltipRow('API Key',item.unknown?t('apiKey.untracked'):maskedAPIKey(item.key));tooltipRow(t('chart.requests'),fmt(item.requests));tooltipRow(t('chart.totalTokens'),formatTokenTotal(item.total_tokens));tooltipRow(t('apiKey.totalCost'),apiKeyShareCostText(item));tooltipRow(t('apiKey.failed'),fmt(item.failed_requests||0));tooltipRow(t('apiKey.share'),percent.toFixed(2)+'%');var cost=apiKeyShareCost(item);if(cost&&cost.unpriced_requests)tooltipRow(t('cost.unpriced'),fmt(cost.unpriced_requests));showTooltip(event);}
function renderAPIKeyShare(){
 var panel=document.getElementById('apiKeySharePanel');if(!panel)return;panel.hidden=!apiKeyTrackingEnabled;if(!apiKeyTrackingEnabled)return;
 var data=currentData||{},rows=(data.api_keys||[]).filter(function(item){return Number(item.requests||0)>0;}).map(function(item){return Object.assign({},item);}),tracked={requests:0,total_tokens:0,failed_requests:0},summary=data.summary||{};
 rows.forEach(function(item){Object.keys(tracked).forEach(function(key){tracked[key]+=Number(item[key]||0);});});
 var missing={ref:'',key:'',requests:Math.max(0,Number(summary.requests||0)-tracked.requests),total_tokens:Math.max(0,Number(summary.total_tokens||0)-tracked.total_tokens),failed_requests:Math.max(0,Number(summary.failed_requests||0)-tracked.failed_requests)};if(missing.requests||missing.total_tokens){missing.unknown=true;rows.push(missing);}
 rows.sort(function(a,b){return apiKeyShareValue(b)-apiKeyShareValue(a)||String(a.ref).localeCompare(String(b.ref));});
 var total=rows.reduce(function(sum,item){return sum+apiKeyShareValue(item);},0),svg=document.getElementById('apiKeyShareDonut'),body=document.getElementById('apiKeyShareRows'),fragment=document.createDocumentFragment(),offset=0;
 svg.replaceChildren(svgNode('circle',{cx:140,cy:140,r:86,class:'donut-track'}));
 rows.forEach(function(item,index){var value=apiKeyShareValue(item),percent=total?value/total*100:0,name=item.unknown?t('apiKey.untracked'):apiKeyShareName(item),row=document.createElement('tr'),cell=apiKeyCell(row,item.ref,'','');row.dataset.apiKeyRef=item.ref;
 cell.querySelector('.apikey-cell-value').textContent=name;var swatch=document.createElement('i');swatch.className='apikey-share-swatch';swatch.style.background=colorFor(index);cell.querySelector('.apikey-cell').prepend(swatch);
 [fmt(item.requests),formatTokenTotal(item.total_tokens),apiKeyShareCostText(item),fmt(item.failed_requests||0),percent.toFixed(1)+'%'].forEach(function(value){var td=document.createElement('td');td.textContent=value;row.appendChild(td);});fragment.appendChild(row);
 if(value>0){var segment=svgNode('circle',{cx:140,cy:140,r:86,pathLength:100,stroke:colorFor(index),'stroke-dasharray':percent+' '+(100-percent),'stroke-dashoffset':-offset,transform:'rotate(-90 140 140)',class:'donut-segment',tabindex:0,role:'img','aria-label':name+' · '+percent.toFixed(1)+'%'}),title=svgNode('title',{});title.textContent=name+' · '+percent.toFixed(1)+'%';segment.appendChild(title);segment.addEventListener('mouseenter',function(event){showAPIKeyShareTooltip(event,item,percent);});segment.addEventListener('mousemove',moveTooltip);segment.addEventListener('mouseleave',hideTooltip);segment.addEventListener('focus',function(event){showAPIKeyShareTooltip(event,item,percent);});segment.addEventListener('blur',hideTooltip);svg.appendChild(segment);offset+=percent;}
 });
 var main=svgNode('text',{x:140,y:137,class:'donut-center-main'});main.textContent=apiKeyShareMetric==='cost'?money(total):apiKeyShareMetric==='tokens'?formatTokenTotal(total):fmt(total);svg.appendChild(main);var sub=svgNode('text',{x:140,y:157,class:'donut-center-sub'});sub.textContent=t(apiKeyShareMetric==='cost'?'apiKey.totalCost':apiKeyShareMetric==='tokens'?'chart.totalTokens':'chart.requests');svg.appendChild(sub);body.replaceChildren(fragment);document.getElementById('apiKeyShareEmpty').hidden=rows.length>0;
 document.querySelectorAll('[data-api-key-share-metric]').forEach(function(button){button.disabled=button.dataset.apiKeyShareMetric==='cost'&&!currentCosts;button.setAttribute('aria-pressed',String(button.dataset.apiKeyShareMetric===apiKeyShareMetric));});
}
document.getElementById('apiKeyShareMetric').addEventListener('click',function(event){var button=event.target.closest('[data-api-key-share-metric]');if(button){apiKeyShareMetric=button.dataset.apiKeyShareMetric;renderAPIKeyShare();}});
`
